# FIMSFit ----
## Setup ----
fit_big_optimized <- FIMS::fit_big_optimized
fit_big_unoptimized <- FIMS:::fit_big_unoptimized
if (!file.exists(testthat::test_path("fixtures", "fit_age_length_comp.RDS"))) {
  suppressWarnings(
    suppressMessages(
      prepare_test_data()
    )
  )
}
fit_age_length_comp <- readRDS(
  testthat::test_path("fixtures", "fit_age_length_comp.RDS")
)

## IO correctness ----
test_that("`is.FIMSFit()` works with correct inputs", {
  #' @description Test that `is.FIMSFit(fit_big_optimized)` returns TRUE.
  expect_true(
    object = is.FIMSFit(fit_big_optimized)
  )

  expected_names <- c(
    "input", "obj", "opt", "max_gradient", "gradient", "report", "sdreport",
    "number_of_parameters", "run_time", "version", "model_output",
    "convergence"
  )
  #' @description Test a FIMSFit object has the correct slot names.
  expect_equal(
    object = slotNames(fit_big_optimized),
    expected = expected_names
  )
})

test_that("`is.FIMSFit()` works with a fit without optimization", {
  #' @description Test that `is.FIMSFit(fit_big_unoptimized)` returns TRUE.
  expect_true(is.FIMSFit(fit_big_unoptimized))
  expect_equal(
    slotNames(fit_big_unoptimized),
    slotNames(fit_big_optimized)
  )
  #' @description Test that a fit without optimization records zero elapsed time.
  expect_equal(fit_big_unoptimized@run_time[["time_total"]], 0)
})

test_that("`fit_fims()` passes `getReportCovariance` to `RTMB::sdreport()`", {
  # The first 5 years of data_big keep the covariance matrix small; weight at
  # age needs 1 more year than the other data
  yearly_types <- c("catch", "index", "age_comp", "length_comp")
  data_5_years <- data_big |>
    dplyr::filter(
      !(.data[["type"]] %in% c(yearly_types, "weight_at_age")) |
        (.data[["type"]] %in% yearly_types & .data[["timing"]] <= 5) |
        (.data[["type"]] == "weight_at_age" & .data[["timing"]] <= 6)
    ) |>
    FIMSFrame()
  fit_with_covariance <- setup_default_parameters(data_5_years) |>
    initialize_fims(data = data_5_years) |>
    fit_fims(number_of_loops = 1, getReportCovariance = TRUE)
  sdreport <- get_sdreport(fit_with_covariance)
  #' @description Test that `getReportCovariance = TRUE` stores the full covariance of the derived quantities.
  expect_equal(
    object = dim(sdreport[["cov"]]),
    expected = rep(length(sdreport[["value"]]), 2)
  )
  expect_true(all(is.finite(diag(sdreport[["cov"]]))))
  clear()
})

test_that("`get_convergence()` works with correct inputs", {
  convergence <- get_convergence(fit_age_length_comp)
  #' @description Test that `get_convergence()` returns 1 row per check run by `fit_fims()` when sdreport is run.
  expect_equal(
    object = convergence[["check"]],
    expected = c(
      "optimizer", "max_gradient", "nll", "hessian", "standard_errors",
      "large_standard_errors", "condition_number"
    )
  )
  #' @description Test that `get_convergence()` stores the maximum gradient of the fit.
  expect_equal(
    object = convergence[["value"]][convergence[["check"]] == "max_gradient"],
    expected = get_max_gradient(fit_age_length_comp),
    tolerance = 1e-8
  )
  #' @description Test that `get_convergence()` has no failed checks for a converged fit.
  expect_false(any(convergence[["severity"]] == "FAIL"))
})

test_that("`print()` shows the convergence status of a fit", {
  flagged_fit <- fit_age_length_comp
  flagged_fit@convergence[["severity"]][
    flagged_fit@convergence[["check"]] == "max_gradient"
  ] <- "WARN"
  #' @description Test that `print()` shows the convergence status and names the flagged check.
  withr::with_options(
    list(rlib_message_verbosity = "default"),
    expect_message(
      print(flagged_fit),
      regexp = "Convergence: \"WARN\" from \"max_gradient\""
    )
  )
})

## Edge handling ----
test_that("`is.FIMSFit()` returns correct outputs for edge cases", {
  #' @description Test that `is.FIMSFit("not_a_FIMSFit")` returns FALSE.
  expect_false(is.FIMSFit("not_a_FIMSFit"))

  # Modify the total run_time to be more than a day
  fit_big_optimized@run_time[["time_total"]] <- 86401 # 60*60*24+1
  #' @description Test that `print(FIMSFit)` returns no error when the total run_time is more than a day.
  expect_no_error(print(fit_big_optimized))

  # Modify the total run_time to be more than a hour
  fit_big_optimized@run_time[["time_total"]] <- 3601 # 60*60+1
  #' @description Test that `print(FIMSFit)` returns no error when the total run_time is more than an hour.
  expect_no_error(print(fit_big_optimized))

  # Modify the total run_time to be more than a minute
  fit_big_optimized@run_time[["time_total"]] <- 61 # 60+1
  #' @description Test that `print(FIMSFit)` returns no error when the total run_time is more than a minute.
  expect_no_error(print(fit_big_optimized))
})

## Error handling ----
test_that("fit_fims() errors when Newton steps are requested", {
  #' @description Test that fit_fims() says to use number_of_loops when Newton steps are requested.
  expect_error(
    fit_fims(input = NULL, number_of_newton_steps = 1),
    regexp = "Newton steps are not implemented yet.*number_of_loops"
  )
})

test_that("fit_fims() errors when optimization fails to converge", {
  # Create a simple test case that will fail to converge by setting
  # extremely restrictive iteration limits
  skip_if(
    Sys.getenv("RUN_SLOW_TESTS") != "true",
    "Skipping: RUN_SLOW_TESTS is not set to true."
  )

  # Skip if test fixtures don't exist
  skip_if_not(file.exists(testthat::test_path("fixtures", "integration_test_data.RData")))

  load(testthat::test_path("fixtures", "integration_test_data.RData"))

  # Set up the model with data
  data_age_comp <- FIMSFrame(data_big)
  parameters <- FIMS::parameters_big

  initialized_model <- parameters |>
    initialize_fims(data = data_age_comp)

  # Set control parameters that will cause convergence failure
  # by making iteration limits extremely low
  bad_control <- list(
    eval.max = 1,
    iter.max = 1,
    trace = 0
  )

  #' @description Test that fit_fims() throws an informative warning when convergence fails.
  expect_warning(
    result <- initialized_model |>
      fit_fims(optimize = TRUE, control = bad_control),
    regexp = "Optimization failed convergence checks"
  )
  #' @description Test that fit_fims() stores a failed optimization check when convergence fails.
  convergence <- get_convergence(result)
  expect_true(any(convergence[["severity"]] == "FAIL"))
  #' @description Test that fit_fims() skips sdreport exactly when the maximum gradient fails.
  gradient_failed <- convergence[["severity"]][
    convergence[["check"]] == "max_gradient"
  ] == "FAIL"
  expect_equal(
    object = length(get_sdreport(result)) == 0,
    expected = gradient_failed
  )

  # Set control parameters that will allow convergence but
  # return large gradient
  bad_control <- list(
    rel.tol = 0.1,
    trace = 0
  )

  #' @description Test that fit_fims() throws an informative error when max gradient is high.
  expect_warning(
    result <- initialized_model |>
      fit_fims(optimize = TRUE, control = bad_control),
    regexp = "Maximum absolute gradient"
  )

  # Where nlminb stops differs across platforms, so this fit can end in any
  # max_gradient severity
  bad_control <- list(
    rel.tol = 1e-8,
    trace = 0
  )

  #' @description Test that fit_fims() runs sdreport unless the maximum gradient fails, for a fit that is stopped earlier than the default.
  result <- suppressWarnings(
    initialized_model |>
      fit_fims(optimize = TRUE, control = bad_control)
  )
  convergence <- get_convergence(result)
  gradient_failed <- convergence[["severity"]][
    convergence[["check"]] == "max_gradient"
  ] == "FAIL"
  expect_equal(
    object = length(get_sdreport(result)) == 0,
    expected = gradient_failed
  )

  #' @description Test that fit_fims() records that the Hessian was not checked when get_sd = FALSE.
  result <- suppressWarnings(
    initialized_model |>
      fit_fims(optimize = TRUE, get_sd = FALSE)
  )
  convergence <- get_convergence(result)
  expect_equal(
    object = convergence[["message"]][convergence[["check"]] == "sdreport"],
    expected = "Hessian not checked because get_sd = FALSE."
  )

  clear()

  # Fix Catch sd at high value in penalized likelihood model to cause high standard errors
  parameters_4_model <- parameters |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_devs",
        timing = 2:get_n_years(data_age_comp),
        estimation_type = "fixed_effects"
      ),
      by = c("label", "timing")
    ) |>
    dplyr::rows_update(
      tibble::tibble(
        module_name = "Recruitment",
        label = "log_sd",
        estimation_type = "constant"
      ),
      by = c("module_name", "label")
    )

  initialized_model <- parameters_4_model |>
    initialize_fims(data = get_data(data_age_comp) |>
      dplyr::rows_update(
        tibble::tibble(
          fleet = "fleet1",
          type = "catch",
          uncertainty = "~dlnorm(meanlog=log_catch_expected, sdlog = 10)",
        ),
        by = c("fleet", "type")
      ) |>
      FIMSFrame())

  #' @description Test that fit_fims() throws an informative warning when parameter SE values are too large.
  expect_warning(
    result <- initialized_model |> fit_fims(optimize = TRUE),
    regexp = "Large condition number detected in Hessian"
  )

  clear()

  # Add an additional slope parameter to make the model overparameterized
  parameters_4_model <- parameters |>
    dplyr::rows_update(
      tibble::tibble(
        fleet = "fleet1",
        label = "log_q",
        estimation_type = "fixed_effects"
      ),
      by = c("fleet", "label")
    )

  initialized_model <- parameters_4_model |>
    initialize_fims(data = data_age_comp)

  #' @description Test that fit_fims() throws an informative warning when the Hessian is not positive definite.
  expect_warning(
    result <- initialized_model |> fit_fims(optimize = TRUE),
    regexp = "Standard error calculations failed convergence checks"
  )

  #' @description Test that fit_fims() returns a non-converged model when you know it is not supposed to converge. The warnings and messages are suppressed because {nlminb} uses backend code that we do not want to print to the screen during testing but we know will be there.
  data("data_big", package = "FIMS")
  data_4_model <- FIMSFrame(data_big)
  # Create parameters
  initialized_poor_model <- setup_default_parameters(data = data_4_model) |>
    dplyr::rows_update(
      tibble::tibble(
        module_name = "Population",
        label = c("log_init_naa"),
        age = 1,
        value = -Inf
      ),
      by = c("module_name", "label", "age")
    ) |>
    initialize_fims(data = data_4_model)
  test_results <- suppressWarnings(suppressMessages(
    fit_fims(initialized_poor_model, optimize = TRUE)
  ))
  expect_true(inherits(test_results, "FIMSFit"))
  expect_equal(get_opt(test_results)[["convergence"]], 1L)
  #' @description Test that fit_fims() stores a failed optimizer check, a failed negative log-likelihood check, and a not-checked Hessian when nlminb fails.
  convergence <- get_convergence(test_results)
  expect_equal(
    object = convergence[["check"]],
    expected = c("optimizer", "nll", "sdreport")
  )
  expect_equal(
    object = convergence[["severity"]],
    expected = c("FAIL", "FAIL", "NOTE")
  )
  #' @description Test that fit_fims() names the objective as not finite when nlminb fails.
  expect_match(
    convergence[["parameter"]][convergence[["check"]] == "nll"],
    "objective"
  )
  expect_equal(
    names(get_opt(test_results)),
    c("par", "objective", "convergence", "message")
  )

  clear()
})

# fit_fims ----
## Setup ----
# 10 years of data_big keep the fits fast. Weight at age has 1 more year, for
# the start of the year after the last model year.
data_10_years <- FIMS::data_big |>
  dplyr::filter(
    is.na(timing) |
      timing <= dplyr::if_else(type == "weight_at_age", 11, 10)
  ) |>
  FIMSFrame()
default_parameters <- setup_default_parameters(data_10_years)

# fleet1's log_Fmort in 2 time blocks, years 1 to 2 and years 3 to 10, so 10
# values share 2 estimates.
blocked_fit <- default_parameters |>
  add_process(
    log_Fmort ~ cut(year, c(-Inf, 2, Inf)),
    module_name = "Fleet",
    fleet = "fleet1"
  ) |>
  initialize_fims(data = data_10_years) |>
  fit_fims()
blocked_estimates <- get_estimates(blocked_fit)

# Every value held constant. The recruitment deviations have no process
# distribution, because a process needs an estimated value to score.
all_constant_input <- default_parameters |>
  dplyr::filter(module_name != "Recruitment") |>
  dplyr::bind_rows(
    setup_default_Recruitment(
      data = data_10_years,
      distribution = NA_character_
    )
  ) |>
  dplyr::mutate(
    estimation_type = dplyr::if_else(
      estimation_type %in% c("fixed_effects", "random_effects"),
      "constant",
      estimation_type
    )
  ) |>
  initialize_fims(data = data_10_years)

## IO correctness ----
test_that("`fit_fims()` gives values that share a map_group 1 estimate", {
  fleet1_log_fmort <- blocked_estimates |>
    dplyr::filter(
      module_name == "Fleet",
      fleet == "fleet1",
      label == "log_Fmort"
    )
  #' @description Test that `fit_fims()` gives every year in a time block from `add_process()` the same estimate.
  expect_equal(
    object = fleet1_log_fmort[["estimated"]],
    expected = rep(fleet1_log_fmort[["estimated"]][c(1, 3)], c(2, 8))
  )
  #' @description Test that `fit_fims()` gives every year in a time block from `add_process()` the same standard error.
  expect_equal(
    object = fleet1_log_fmort[["uncertainty"]],
    expected = rep(fleet1_log_fmort[["uncertainty"]][c(1, 3)], c(2, 8))
  )
  #' @description Test that `fit_fims()` gives the shared estimates of a time block finite standard errors.
  expect_true(all(is.finite(fleet1_log_fmort[["uncertainty"]])))
  #' @description Test that `fit_fims()` reports the gradient of a shared estimate only on the first year of its time block.
  expect_equal(
    object = is.na(fleet1_log_fmort[["gradient"]]),
    expected = !(seq_len(10) %in% c(1, 3))
  )
  unblocked_fit <- default_parameters |>
    initialize_fims(data = data_10_years) |>
    fit_fims(optimize = FALSE)
  #' @description Test that `fit_fims()` counts 2 fixed effects, not 10, for 10 years of log_Fmort in 2 time blocks.
  expect_equal(
    object = get_number_of_parameters(blocked_fit)[["fixed_effects"]],
    expected = get_number_of_parameters(unblocked_fit)[["fixed_effects"]] - 8
  )
})

test_that("`fit_fims()` holds constant values at their starting values", {
  constant_rows <- blocked_estimates |>
    dplyr::filter(estimation_type == "constant")
  #' @description Test that `fit_fims()` gives every constant value an NA standard error.
  expect_true(all(is.na(constant_rows[["uncertainty"]])))
  #' @description Test that `fit_fims()` keeps every constant value at its starting value.
  expect_equal(
    object = constant_rows[["estimated"]],
    expected = constant_rows[["input"]]
  )
})

test_that("`fit_fims()` gives the same values as RTMB's default tape settings", {
  # The recruitment deviations are random effects, so the Laplace
  # approximation and its Hessian are part of the comparison.
  fit <- default_parameters |>
    initialize_fims(data = data_10_years) |>
    fit_fims()
  obj <- get_obj(fit)
  starting_values <- obj[["par"]]
  objective <- obj[["fn"]](starting_values)
  gradient <- obj[["gr"]](starting_values)
  # fit_fims() restored the session's settings, which are RTMB's defaults
  # here, so retaping records the same model without atomic matrix products.
  obj[["retape"]]()
  #' @description Test that `fit_fims()` gives the same objective as a tape with RTMB's default settings.
  expect_equal(
    object = obj[["fn"]](starting_values),
    expected = objective
  )
  # The gradient is compared at the starting values, where it is far from 0,
  # so a relative difference is meaningful.
  #' @description Test that `fit_fims()` gives the same gradient as a tape with RTMB's default settings.
  expect_equal(
    object = obj[["gr"]](starting_values),
    expected = gradient
  )
  par <- get_opt(fit)[["par"]]
  # fn() moves last.par.best, which FIMSFit() reports from, to the estimates
  obj[["fn"]](par)
  default_tape_fit <- FIMSFit(
    input = get_input(fit),
    obj = obj,
    opt = get_opt(fit),
    sdreport = RTMB::sdreport(obj, par.fixed = par)
  )
  # The gradient at the estimates is close to 0, so its relative differences
  # are large and it is left out here.
  #' @description Test that `fit_fims()` gives the same estimates and standard errors as a tape with RTMB's default settings.
  expect_equal(
    object = get_estimates(default_tape_fit) |>
      dplyr::select(-"gradient"),
    expected = get_estimates(fit) |>
      dplyr::select(-"gradient")
  )
})

test_that("`fit_fims()` restores the user's tape settings", {
  default_tape_config <- RTMB::TapeConfig()
  withr::defer(RTMB::TapeConfig(default_tape_config))
  # Plain products, which fit_fims() changes, and a plain multivariate normal,
  # which is not RTMB's default, so both a reset to the defaults and leaving
  # fit_fims()'s setting would fail
  user_tape_config <- RTMB::TapeConfig(atomic = "disable")
  fit_fims(all_constant_input, optimize = FALSE)
  #' @description Test that `fit_fims()` puts back the user's `RTMB::TapeConfig()` settings when it returns.
  expect_equal(
    object = RTMB::TapeConfig(),
    expected = user_tape_config
  )
})

## Edge handling ----
test_that("`fit_fims()` returns correct outputs for edge cases", {
  random_effects_only_fit <- default_parameters |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        estimation_type == "fixed_effects",
        "constant",
        estimation_type
      )
    ) |>
    initialize_fims(data = data_10_years) |>
    fit_fims()
  random_effects <- get_estimates(random_effects_only_fit) |>
    dplyr::filter(estimation_type == "random_effects")
  #' @description Test that `fit_fims()` with every fixed effect constant counts 0 fixed effects and 9 random effects, the recruitment deviations in years 2 to 10.
  expect_equal(
    object = get_number_of_parameters(random_effects_only_fit),
    expected = c(fixed_effects = 0, random_effects = 9)
  )
  #' @description Test that `fit_fims()` with every fixed effect constant evaluates the model without an outer optimizer.
  expect_equal(
    object = get_opt(random_effects_only_fit)[["message"]],
    expected = "No fixed effects to optimize"
  )
  #' @description Test that `fit_fims()` with every fixed effect constant reports a maximum gradient of 0.
  expect_equal(
    object = get_max_gradient(random_effects_only_fit),
    expected = 0
  )
  #' @description Test that `fit_fims()` with every fixed effect constant still estimates the random effects, which move from their starting values of 0.
  expect_true(all(random_effects[["estimated"]] != random_effects[["input"]]))
  #' @description Test that `fit_fims()` with every fixed effect constant gives the random effects finite standard errors.
  expect_true(all(is.finite(random_effects[["uncertainty"]])))

  all_constant_fit <- fit_fims(all_constant_input, optimize = FALSE)
  #' @description Test that `fit_fims(optimize = FALSE)` with every value constant counts 0 fixed effects and 0 random effects.
  expect_equal(
    object = get_number_of_parameters(all_constant_fit),
    expected = c(fixed_effects = 0, random_effects = 0)
  )
  #' @description Test that `fit_fims(optimize = FALSE)` with every value constant gives every row an NA standard error.
  expect_true(all(is.na(get_estimates(all_constant_fit)[["uncertainty"]])))
})

## Error handling ----
test_that("`fit_fims()` returns correct error messages", {
  #' @description Test that `fit_fims()` errors when every value is constant and `optimize = TRUE`.
  expect_error(
    object = fit_fims(all_constant_input),
    regexp = "at least one parameter to optimize"
  )
  p_map_input <- initialize_fims(default_parameters, data = data_10_years)
  p_map_input[["map"]] <- list(p = factor(1))
  #' @description Test that `fit_fims()` errors with a pointer to `map_group` when `input[["map"]]` names something that is not a model parameter, such as `p`.
  expect_error(
    object = fit_fims(p_map_input, optimize = FALSE),
    regexp = "map_group"
  )
  #' @description Test that `fit_fims()` errors for an input that did not come from `initialize_fims()`.
  expect_error(
    object = fit_fims(list(a = 1)),
    regexp = "not a model from"
  )
  #' @description Test that `fit_fims()` errors for `get_sd = NA` before fitting.
  expect_error(
    object = fit_fims(all_constant_input, get_sd = NA),
    regexp = "`get_sd` is not `TRUE` or `FALSE`"
  )
  #' @description Test that `fit_fims()` errors for `number_of_loops = NA` before fitting.
  expect_error(
    object = fit_fims(all_constant_input, number_of_loops = NA),
    regexp = "must be 1 number >= 0"
  )
})
